#!/usr/bin/env bash
# GSZ step145 — Netflix FULL-account fulfilment from the portal. New lib/nfPortal.js
# (guarded POST /internal/assign). Hooked into the admin deliver path: marking a
# full-account Netflix order delivered with NO credentials auto-assigns a free
# account from the portal and delivers it (login + account email) + notifies.
# Owner-controlled, works for every payment method. Patches lib/deliver.js.
# No migration. Idempotent; restores on failure. Robust health check.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step145-$TS"; TMP=$(mktemp -d)
PATCHED=(lib/deliver.js)
NEW=(lib/nfPortal.js)
echo "==> step145: Netflix full-account portal fulfilment"
mkdir -p "$BK/lib"; for f in "${PATCHED[@]}"; do cp "$GSZ/$f" "$BK/$f"; done
NEWHAD=()
for f in "${NEW[@]}"; do if [ -f "$GSZ/$f" ]; then NEWHAD+=("$f"); cp "$GSZ/$f" "$BK/$f"; fi; done
echo "    backup: $BK"
restore(){
  echo "!! FAILED — restoring"
  for f in "${PATCHED[@]}"; do cp "$BK/$f" "$GSZ/$f"; done
  for f in "${NEW[@]}"; do keep=0; for h in "${NEWHAD[@]:-}"; do [ "$h" = "$f" ] && keep=1; done; if [ "$keep" = "1" ]; then cp "$BK/$f" "$GSZ/$f"; else rm -f "$GSZ/$f"; fi; done
  pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."
}
trap 'restore' ERR
echo "==> writing new files"; mkdir -p "$GSZ/lib"
echo ""   | base64 -d > "$GSZ/lib/nfPortal.js"
echo "" | base64 -d > "$TMP/p.js"
echo "==> applying patches"; node "$TMP/p.js" "$GSZ"
echo "==> validating"; node --check "$GSZ/lib/nfPortal.js"; node --check "$GSZ/lib/deliver.js"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
echo "==> waiting for app to come up"
CODE=000
for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] && echo "    homepage 200: OK (after ${i}s)" || { echo "    homepage $CODE after ${i}s"; false; }
trap - ERR; rm -rf "$TMP"
echo ""
echo "==> step145 OK ✅  Full-account Netflix: on an order page, set the plan's portal product on /admin/netflix, then click 'Deliver & notify customer' with the credentials box BLANK — GSZ pulls a free account from your portal and delivers it. (Screen plans keep auto-delivering from Inventory.)"
